<script setup>
defineProps({ session: Object, busy: Boolean, pending: Boolean, canAnswer: Boolean, answer: String });
const emit = defineEmits(['update:answer', 'confirm', 'answer', 'new-task']);
</script>
<template><section v-if="session" class="collaboration-ui" aria-live="polite"><header><span class="status-dot" :class="session.status" /> <strong>{{ session.message || session.status }}</strong></header><p v-if="session.error" class="error" role="alert">{{ session.error }}</p><ul v-if="session.progress?.stages?.length" class="stages"><li v-for="stage in session.progress.stages" :key="stage.id"><i :class="stage.status" />{{ stage.label }}<small>{{ stage.message || stage.status }}</small></li></ul><div v-if="session.questions?.length" class="questions"><p v-for="(question,index) in session.questions" :key="index">{{ typeof question === 'string' ? question : question.text || question.question || JSON.stringify(question) }}</p><textarea :value="answer" :disabled="!canAnswer" rows="2" placeholder="补充说明" @input="emit('update:answer', $event.target.value)" /><button type="button" :disabled="!canAnswer || !answer?.trim()" @click="emit('answer')">回复</button></div><div v-if="session.confirmation" class="confirmation"><pre>{{ session.confirmation.confirmed_prompt_zh }}</pre><pre>{{ session.confirmation.execution_prompt_en }}</pre><button type="button" :disabled="busy" @click="emit('confirm')">确认并生成</button></div></section></template>
<style scoped>.collaboration-ui{box-sizing:border-box;flex:1;height:100%;min-height:0;overflow:auto;display:grid;gap:10px;padding:14px 18px;border-top:1px solid #ffffff18;background:#181b1d;color:#dfe6de;font-size:12px}.collaboration-ui header{display:flex;align-items:center;gap:8px}.status-dot{width:8px;height:8px;border-radius:50%;background:#9ba39a}.status-dot.queued,.status-dot.running{background:#d8b45f}.status-dot.awaiting_confirmation{background:#b7f34a}.status-dot.failed{background:#ed8b83}.error{margin:0;color:#f0a09a}.stages{display:grid;gap:6px;margin:0;padding:0;list-style:none}.stages li{display:flex;align-items:center;gap:7px;color:#abb5aa}.stages i{width:6px;height:6px;border-radius:50%;background:#727b72}.stages i.running{background:#d8b45f}.stages i.completed{background:#b7f34a}.stages small{margin-left:auto;color:#7e897e}.questions,.confirmation{display:grid;gap:8px}.questions p{margin:0}.questions textarea{width:100%;resize:vertical;padding:8px;border:1px solid #ffffff20;border-radius:6px;background:#111415;color:inherit}.questions button,.confirmation button{justify-self:start;padding:7px 11px;border:1px solid #ffffff20;border-radius:6px;background:#2b3727;color:#d9f7b7}.confirmation pre{max-height:130px;margin:0;padding:9px;overflow:auto;white-space:pre-wrap;border-radius:6px;background:#111415;color:#bbc6bb;font:11px/1.6 ui-monospace,Consolas,monospace}.collaboration-ui button:disabled,.questions textarea:disabled{opacity:.5;cursor:default}</style>
